use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => return Some(out),
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            other => cur.push(other),
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
}

/// Accept either a JSON array of strings or newline/comma-separated text.
fn parse_urls(raw: &str) -> Vec<String> {
    let items: Vec<String> = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect(),
    };
    let mut seen: Vec<String> = Vec::new();
    for item in items {
        let t = item.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !seen.iter().any(|u| u == t) {
            seen.push(t.to_string());
        }
    }
    seen
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
```

